class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.prices = {symbol: [] for symbol in self.symbols}

        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.strategy_a_sma_values = []
        self.spy_sma = self.SMA("SPY", 20, Resolution.Daily)

        self.aapl_rsi = self.RSI("AAPL", 14, Resolution.Daily)

    def OnData(self, data):
        if not all(symbol in data and data[symbol] for symbol in self.symbols):
            return

        for symbol in self.symbols:
            self.prices[symbol].append(data[symbol].Close)

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        self.strategy_a_sma_values.append(self.spy_sma.Current.Value)

        spy_shares = self.Portfolio['SPY'].Quantity
        aapl_shares = self.Portfolio['AAPL'].Quantity

        # Evaluate sells before buys

        # Strategy A sell
        if spy_shares > 0:
            prev_close = self.prices['SPY'][-2]
            curr_close = self.prices['SPY'][-1]
            prev_sma = self.strategy_a_sma_values[-2]
            curr_sma = self.strategy_a_sma_values[-1]

            if prev_close >= prev_sma and curr_close < curr_sma:
                self.MarketOrder("SPY", -spy_shares)

        # Strategy B sell
        if aapl_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder("AAPL", -aapl_shares)

        # Strategy A buy
        if spy_shares == 0:
            prev_close = self.prices['SPY'][-2]
            curr_close = self.prices['SPY'][-1]
            prev_sma = self.strategy_a_sma_values[-2]
            curr_sma = self.strategy_a_sma_values[-1]

            if prev_close <= prev_sma and curr_close > curr_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.40
                curr_price = self.prices['SPY'][-1]
                shares_to_buy = int(invest_amount / curr_price)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)

        # Strategy B buy
        if aapl_shares == 0:
            aapl_closes = self.prices['AAPL']
            if len(aapl_closes) >= 4:
                if (aapl_closes[-1] < aapl_closes[-2] and
                    aapl_closes[-2] < aapl_closes[-3] and
                    aapl_closes[-3] < aapl_closes[-4]):
                    available_cash = self.Portfolio.Cash
                    if available_cash >= 20000:
                        curr_price = self.prices['AAPL'][-1]
                        shares_to_buy = int(20000 / curr_price)
                        if shares_to_buy > 0:
                            self.MarketOrder("AAPL", shares_to_buy)

from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_period = 20
        self.aapl_rsi_period = 14

        self.spy_closes = []
        self.aapl_closes = []

        self.spy_prev_sma = None
        self.spy_prev_close = None

    def OnData(self, data):
        for ticker, symbol in self.symbols.items():
            if not data.ContainsKey(symbol):
                return

        spy_symbol = self.symbols['SPY']
        aapl_symbol = self.symbols['AAPL']

        spy_close = data[spy_symbol].Close
        aapl_close = data[aapl_symbol].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        spy_sma = None
        if len(self.spy_closes) >= self.spy_sma_period:
            spy_sma = sum(self.spy_closes[-self.spy_sma_period:]) / self.spy_sma_period

        aapl_rsi = None
        if len(self.aapl_closes) >= self.aapl_rsi_period + 1:
            aapl_rsi = self.calculate_rsi(self.aapl_closes, self.aapl_rsi_period)

        aapl_red_count = 0
        if len(self.aapl_closes) > 1:
            for i in range(len(self.aapl_closes) - 1, 0, -1):
                if self.aapl_closes[i] < self.aapl_closes[i-1]:
                    aapl_red_count += 1
                else:
                    break

        spy_position = self.Portfolio[spy_symbol].Quantity
        aapl_position = self.Portfolio[aapl_symbol].Quantity

        if spy_position > 0 and spy_sma is not None and self.spy_prev_sma is not None:
            if self.spy_prev_close >= self.spy_prev_sma and spy_close < spy_sma:
                self.Liquidate(spy_symbol)

        if spy_position == 0 and spy_sma is not None and self.spy_prev_sma is not None:
            if self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.Buy(spy_symbol, shares_to_buy)

        if aapl_position > 0 and aapl_rsi is not None:
            if aapl_rsi > 60:
                self.Liquidate(aapl_symbol)

        if aapl_position == 0 and aapl_red_count >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                shares_to_buy = int(20000 / aapl_close)
                if shares_to_buy > 0:
                    self.Buy(aapl_symbol, shares_to_buy)

        self.spy_prev_close = spy_close
        if spy_sma is not None:
            self.spy_prev_sma = spy_sma

    def calculate_rsi(self, closes, period):
        if len(closes) < period + 1:
            return None

        gains = 0
        losses = 0
        for i in range(-period, 0):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

