        aapl_qty = self.Portfolio["AAPL"].Quantity

        if spy_qty > 0 and self.prev_spy_sma is not None:
            prev_spy_close = self.spy_closes[-2]
            if prev_spy_close >= self.prev_spy_sma and spy_bar.Close < curr_spy_sma:
                self.MarketOrder("SPY", -spy_qty)
                spy_qty = 0

        if aapl_qty > 0:
            if curr_aapl_rsi > 60:
                self.MarketOrder("AAPL", -aapl_qty)
                aapl_qty = 0

        if spy_qty == 0 and self.prev_spy_sma is not None:
            prev_spy_close = self.spy_closes[-2]
            if prev_spy_close <= self.prev_spy_sma and spy_bar.Close > curr_spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.40
                shares_to_buy = int(invest_amount / spy_bar.Close)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)

        if aapl_qty == 0 and self.aapl_consecutive_red >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                shares_to_buy = int(20000 / aapl_bar.Close)
                if shares_to_buy > 0:
                    self.MarketOrder("AAPL", shares_to_buy)

        self.prev_spy_sma = curr_spy_sma

    def calculate_rsi(self, closes):
        if len(closes) < self.rsi_period:
            return 50

        recent = closes[-self.rsi_period:]
        gains = 0.0
        losses = 0.0

        for i in range(1, len(recent)):
            change = recent[i] - recent[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

