from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](21)
        self.aapl_closes = RollingWindow[float](15)

        self.SetWarmupPeriod(20)

    def OnData(self, data):
        # Check all symbols have data
        for sym in self.symbols:
            if sym not in data:
                return

        spy_price = data[self.spy].Close
        aapl_price = data[self.aapl].Close

        self.spy_closes.Add(spy_price)
        self.aapl_closes.Add(aapl_price)

        if self.spy_closes.Count < 21 or self.aapl_closes.Count < 15:
            return

        spy_list = list(self.spy_closes)
        aapl_list = list(self.aapl_closes)

        # Calculate SPY SMA
        spy_sma_today = sum(spy_list[0:20]) / 20.0
        spy_sma_yesterday = sum(spy_list[1:21]) / 20.0

        # Calculate AAPL RSI
        aapl_rsi = self._compute_rsi(aapl_list)

        # Count AAPL consecutive red days
        red_days = 0
        for i in range(len(aapl_list) - 1):
            if aapl_list[i] < aapl_list[i + 1]:
                red_days += 1
            else:
                break

        # Strategy A (SPY) - sell before buy
        if self.Portfolio[self.spy].Quantity > 0:
            if spy_list[1] >= spy_sma_yesterday and spy_list[0] < spy_sma_today:
                self.Liquidate(self.spy)
        elif spy_list[1] <= spy_sma_yesterday and spy_list[0] > spy_sma_today:
            portfolio_value = self.Portfolio.TotalPortfolioValue
            amount = portfolio_value * 0.4
            shares = int(amount / spy_price)
            if shares > 0:
                self.Buy(self.spy, shares)

        # Strategy B (AAPL) - sell before buy
        if self.Portfolio[self.aapl].Quantity > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.aapl)
        elif red_days >= 3:
            cash = self.Portfolio.Cash
            if cash >= 20000:
                shares = int(20000 / aapl_price)
                if shares > 0:
                    self.Buy(self.aapl, shares)

    def _compute_rsi(self, prices):
        prices_chron = list(reversed(prices))

        gains = 0.0
        losses = 0.0
        for i in range(1, len(prices_chron)):
            diff = prices_chron[i] - prices_chron[i - 1]
            if diff > 0:
                gains += diff
            else:
                losses -= diff

        avg_gain = gains / 14.0
        avg_loss = losses / 14.0

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 0.0

        rs = avg_gain / avg_loss
        return 100.0 - (100.0 / (1.0 + rs))

