    def _compute_rsi(self, prices):
        prices_chron = list(reversed(prices))

        gains = 0.0
        losses = 0.0
        for i in range(1, len(prices_chron)):
            diff = prices_chron[i] - prices_chron[i - 1]
            if diff > 0:
                gains += diff
            else:
                losses -= diff

        avg_gain = gains / 14.0
        avg_loss = losses / 14.0

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 0.0

        rs = avg_gain / avg_loss
        return 100.0 - (100.0 / (1.0 + rs))
