        self.RegisterIndicator("AAPL", self.aapl_rsi, Resolution.Daily)

        self.spy_prev_close = None
        self.aapl_prev_close = None
        self.aapl_consecutive_red = 0

    def OnData(self, data):
        if not all(ticker in data and data[ticker] is not None for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]):
            return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_consecutive_red += 1
            else:
                self.aapl_consecutive_red = 0

        if not self.spy_ma.IsReady or not self.aapl_rsi.IsReady:
            self.spy_prev_close = spy_close
            self.aapl_prev_close = aapl_close
            return

        spy_quantity = self.Portfolio["SPY"].Quantity
        aapl_quantity = self.Portfolio["AAPL"].Quantity

        if spy_quantity > 0:
            if self.crosses_below(spy_close, self.spy_prev_close, self.spy_ma.Current.Value):
                self.Liquidate("SPY")

        if aapl_quantity > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate("AAPL")

        if spy_quantity == 0:
            if self.crosses_above(spy_close, self.spy_prev_close, self.spy_ma.Current.Value):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount_to_invest = portfolio_value * 0.4
                shares_to_buy = int(amount_to_invest / spy_close)
                if shares_to_buy > 0:
                    self.BuyMarketOrder("SPY", shares_to_buy)

        if aapl_quantity == 0:
            if self.aapl_consecutive_red >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.BuyMarketOrder("AAPL", shares_to_buy)

        self.spy_prev_close = spy_close
        self.aapl_prev_close = aapl_close

    def crosses_above(self, current, previous, level):
        if previous is None:
            return False
        return previous <= level and current > level

    def crosses_below(self, current, previous, level):
        if previous is None:
            return False
        return previous >= level and current < level

