        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.AddEquity(ticker, Resolution.Daily)

        self.strategy_a_shares = 0
        self.spy_closes = []

        self.strategy_b_shares = 0
        self.aapl_closes = []
        self.aapl_red_count = 0

    def OnData(self, data):
        if not all(data.ContainsKey(t) for t in ["SPY", "AAPL", "IBM", "BAC", "AIG"]):
            return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) > 21:
            self.spy_closes.pop(0)
        if len(self.aapl_closes) > 15:
            self.aapl_closes.pop(0)

        if len(self.spy_closes) < 21 or len(self.aapl_closes) < 15:
            return

        today_ma = sum(self.spy_closes[-20:]) / 20
        yesterday_ma = sum(self.spy_closes[-21:-1]) / 20
        today_close = self.spy_closes[-1]
        yesterday_close = self.spy_closes[-2]

        if self.aapl_closes[-1] < self.aapl_closes[-2]:
            self.aapl_red_count += 1
        else:
            self.aapl_red_count = 0

        rsi = self.calculate_rsi(self.aapl_closes[-14:])

        if self.strategy_a_shares > 0:
            if yesterday_close >= yesterday_ma and today_close < today_ma:
                self.MarketOrder("SPY", -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif self.strategy_a_shares == 0:
            if yesterday_close <= yesterday_ma and today_close > today_ma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)
                    self.strategy_a_shares = shares_to_buy

        if self.strategy_b_shares > 0:
            if rsi > 60:
                self.MarketOrder("AAPL", -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.strategy_b_shares == 0:
            if self.aapl_red_count >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder("AAPL", shares_to_buy)
                        self.strategy_b_shares = shares_to_buy

    def calculate_rsi(self, closes):
        if len(closes) < 14:
            return None

        gains_sum = 0
        losses_sum = 0

        for i in range(1, 14):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains_sum += change
            else:
                losses_sum += abs(change)

        avg_gain = gains_sum / 13
        avg_loss = losses_sum / 13

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

