            if spy_prev_close >= spy_sma_100_yesterday and spy_close < spy_sma_100_today:
                self.Liquidate(self.strategy_a_symbol)

        if aapl_holdings > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.strategy_b_symbol)

