        gains = sum(max(0, prices[i] - prices[i-1]) for i in range(1, len(prices)))
        losses = sum(max(0, prices[i-1] - prices[i]) for i in range(1, len(prices)))

        n = len(prices) - 1
        avg_gain = gains / n
        avg_loss = losses / n

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

