        prices = {ticker: data[ticker].Close for ticker in self.securities}

        self.spy_prices.append(prices["SPY"])
        self.aapl_closes.append(prices["AAPL"])

        if len(self.spy_prices) < 101 or len(self.aapl_closes) < 15:
            return

        today_spy_sma = sum(self.spy_prices[-100:]) / 100
        yesterday_spy_sma = sum(self.spy_prices[-101:-1]) / 100
        today_spy = self.spy_prices[-1]
        yesterday_spy = self.spy_prices[-2]

        aapl_rsi = self._calculate_rsi(self.aapl_closes[-15:])

        red_days = 0
        for i in range(len(self.aapl_closes) - 1, 0, -1):
            if self.aapl_closes[i] < self.aapl_closes[i - 1]:
                red_days += 1
            else:
                break

        if self.aapl_lot > 0 and aapl_rsi > 60:
            self.Liquidate("AAPL")
            self.aapl_lot = 0

        if self.spy_lot > 0:
