                self.Liquidate("SPY")
                self.spy_lot = 0

        if self.spy_lot == 0:
            if yesterday_spy <= yesterday_spy_sma and today_spy > today_spy_sma:
                invest_amount = self.Portfolio.TotalPortfolioValue * 0.4
                shares = int(invest_amount / today_spy)
                self.Buy("SPY", shares)
                self.spy_lot = shares

        if self.aapl_lot == 0:
            if red_days >= 3 and self.Portfolio.Cash >= 20000:
                shares = int(20000 / prices["AAPL"])
                self.Buy("AAPL", shares)
                self.aapl_lot = shares

