            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / (len(closes) - 1)
        avg_loss = losses / (len(closes) - 1)

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        return 100.0 - (100.0 / (1.0 + rs))

