class QuantConnectLeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        # Strategy A: SPY with 100-day SMA
        self.spy_closes = []
        self.spy_smas = []

        # Strategy B: AAPL with red day counter and 14-day RSI
        self.aapl_closes = []
        self.aapl_prev_close = None
        self.aapl_red_days = 0

    def OnData(self, data):
        # Check if all symbols have data
        for symbol in self.symbols:
            if symbol not in data:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        # Store closes
        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        # Compute SPY 100-day SMA if we have 100 closes
        if len(self.spy_closes) >= 100:
            sma = sum(self.spy_closes[-100:]) / 100.0
            self.spy_smas.append(sma)

        # Update AAPL red day counter (do this every bar)
        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        self.aapl_prev_close = aapl_close

        # Check if we have enough data to trade
        # Need 2 SMAs for SPY cross detection and 14 closes for AAPL RSI
        if len(self.spy_smas) < 2 or len(self.aapl_closes) < 14:
            return

        # Compute AAPL 14-day RSI
        aapl_rsi = self.calculate_rsi(self.aapl_closes[-14:])

        # Process strategies (evaluate sells before buys)
        self.process_strategy_a(spy_close)
        self.process_strategy_b(aapl_close, aapl_rsi)

    def process_strategy_a(self, spy_close):
        prev_close = self.spy_closes[-2]
        prev_sma = self.spy_smas[-2]
        curr_sma = self.spy_smas[-1]

        # Sell first (if holding)
        if self.Portfolio["SPY"].Quantity > 0:
            # Cross below: yesterday close >= yesterday SMA, today close < today SMA
            if prev_close >= prev_sma and spy_close < curr_sma:
                self.Liquidate("SPY")

        # Buy second (if not holding)
        if self.Portfolio["SPY"].Quantity == 0:
            # Cross above: yesterday close <= yesterday SMA, today close > today SMA
            if prev_close <= prev_sma and spy_close > curr_sma:
                self.SetHoldings("SPY", 0.40)

    def process_strategy_b(self, aapl_close, aapl_rsi):
        # Sell first (if holding)
        if self.Portfolio["AAPL"].Quantity > 0:
            if aapl_rsi > 60:
                self.Liquidate("AAPL")

        # Buy second (if not holding)
        if self.Portfolio["AAPL"].Quantity == 0:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder("AAPL", shares)

    def calculate_rsi(self, prices):
        if len(prices) < 14:
            return 50

        gains = 0.0
        losses = 0.0

        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / 14.0
        avg_loss = losses / 14.0

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

