        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 101 or len(self.aapl_closes) < 15:
            return

        sma_today = np.mean(self.spy_closes[-100:])
        sma_yesterday = np.mean(self.spy_closes[-101:-1])
        spy_today = self.spy_closes[-1]
        spy_yesterday = self.spy_closes[-2]

        aapl_rsi = self.calculate_rsi(self.aapl_closes[-15:])

        red_count = 0
        for i in range(len(self.aapl_closes) - 1, 0, -1):
            if self.aapl_closes[i] < self.aapl_closes[i-1]:
                red_count += 1
            else:
                break

        if self.strategy_a_lots > 0:
            if spy_yesterday >= sma_yesterday and spy_today < sma_today:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lots)
                self.strategy_a_lots = 0

        if self.strategy_a_lots == 0:
            if spy_yesterday <= sma_yesterday and spy_today > sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares = int(invest_amount / spy_today)
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)
                    self.strategy_a_lots = shares

        if self.strategy_b_lots > 0:
            if aapl_rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lots)
                self.strategy_b_lots = 0

        if self.strategy_b_lots == 0:
            if red_count >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)
                        self.strategy_b_lots = shares

    def calculate_rsi(self, prices):
        if len(prices) < 15:
            return None

        changes = [prices[i] - prices[i-1] for i in range(1, len(prices))]
        gains = sum(c for c in changes if c > 0)
        losses = -sum(c for c in changes if c < 0)

        avg_gain = gains / 14
        avg_loss = losses / 14

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

