class QuantConnectLeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.sma100_spy = self.SMA(self.spy, 100)
        self.rsi14_aapl = self.RSI(self.aapl, 14)

        self.prev_close_spy = None
        self.prev_close_aapl = None
        self.red_streak_aapl = 0

    def OnData(self, data):
        if not (data.ContainsKey(self.spy) and data.ContainsKey(self.aapl) and 
                data.ContainsKey(self.ibm) and data.ContainsKey(self.bac) and 
                data.ContainsKey(self.aig)):
            return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        if self.prev_close_spy is None:
            self.prev_close_spy = spy_close
            self.prev_close_aapl = aapl_close
            return

        if not self.sma100_spy.IsReady or not self.rsi14_aapl.IsReady:
            self.prev_close_spy = spy_close
            self.prev_close_aapl = aapl_close
            return

        if aapl_close < self.prev_close_aapl:
            self.red_streak_aapl += 1
        else:
            self.red_streak_aapl = 0

        self.process_slot1(spy_close)
        self.process_slot2(aapl_close)

        self.prev_close_spy = spy_close
        self.prev_close_aapl = aapl_close

    def process_slot1(self, spy_close):
        sma100 = self.sma100_spy.Current.Value
        current_lot = self.Portfolio[self.spy].Quantity

        if current_lot > 0:
            if self.prev_close_spy > sma100 and spy_close <= sma100:
                self.MarketOrder(self.spy, -current_lot)
                return

        if current_lot == 0:
            if self.prev_close_spy <= sma100 and spy_close > sma100:
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                shares = int(target_value / spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)

    def process_slot2(self, aapl_close):
        rsi = self.rsi14_aapl.Current.Value
        current_lot = self.Portfolio[self.aapl].Quantity

        if current_lot > 0:
            if rsi > 60:
                self.MarketOrder(self.aapl, -current_lot)
                return

        if current_lot == 0:
            if self.red_streak_aapl >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)

