        if len(self.aapl_closes) >= 2:
            if self.aapl_closes[-1] < self.aapl_closes[-2]:
                self.aapl_consecutive_red += 1
            else:
                self.aapl_consecutive_red = 0

        if spy_ma100 is None or aapl_rsi14 is None or len(self.spy_closes) < 101:
            return

        spy_ma100_prev = sum(self.spy_closes[-101:-1]) / 100.0
        spy_close_curr = self.spy_closes[-1]
        spy_close_prev = self.spy_closes[-2]

        if self.spy_shares > 0:
            if spy_close_prev >= spy_ma100_prev and spy_close_curr < spy_ma100:
                self.Sell(self.symbols['SPY'], self.spy_shares)
                self.spy_shares = 0

        if self.aapl_shares > 0:
            if aapl_rsi14 > 60:
                self.Sell(self.symbols['AAPL'], self.aapl_shares)
                self.aapl_shares = 0

        if self.spy_shares == 0:
            if spy_close_prev <= spy_ma100_prev and spy_close_curr > spy_ma100:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / spy_close_curr)
                if shares > 0:
                    self.Buy(self.symbols['SPY'], shares)
                    self.spy_shares = shares

        if self.aapl_shares == 0:
            if self.aapl_consecutive_red >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.symbols['AAPL'], shares)
                        self.aapl_shares = shares

    def _rsi(self, period):
        if len(self.aapl_closes) < period + 1:
            return None
        closes = self.aapl_closes[-(period+1):]
        ups = 0
        downs = 0
        for i in range(1, len(closes)):
            delta = closes[i] - closes[i-1]
            if delta > 0:
                ups += delta
            else:
                downs -= delta
        avg_up = ups / period
        avg_down = downs / period
        if avg_down == 0:
            return 100.0
        rs = avg_up / avg_down
        return 100.0 - 100.0 / (1.0 + rs)

